class NoteContainer(object):

    """A container for notes.

    The NoteContainer provides a container for the mingus.containers.Note
    objects.

    It can be used to store single and multiple notes and is required for
    working with Bars.
    """

    notes = []

    def __init__(self, notes=None):
        if notes is None:
            notes = []
        self.empty()
        self.add_notes(notes)

    def empty(self):
        """Empty the container."""
        self.notes = []

    def add_note(self, note, octave=None, dynamics=None):
        """Add a note to the container and sorts the notes from low to high.

        The note can either be a string, in which case you could also use
        the octave and dynamics arguments, or a Note object.
        """
        if dynamics is None:
            dynamics = {}
        if isinstance(note, six.string_types):
            if octave is not None:
                note = Note(note, octave, dynamics)
            elif len(self.notes) == 0:
                note = Note(note, 4, dynamics)
            else:
                if Note(note, self.notes[-1].octave) < self.notes[-1]:
                    note = Note(note, self.notes[-1].octave + 1, dynamics)
                else:
                    note = Note(note, self.notes[-1].octave, dynamics)
        if not hasattr(note, "name"):
            raise UnexpectedObjectError(
                "Object '%s' was not expected. "
                "Expecting a mingus.containers.Note object." % note
            )
        if note not in self.notes:
            self.notes.append(note)
            self.notes.sort()
        return self.notes

    def add_notes(self, notes):
        """Feed notes to self.add_note.

        The notes can either be an other NoteContainer, a list of Note
        objects or strings or a list of lists formatted like this:
        >>> notes = [['C', 5], ['E', 5], ['G', 6]]

        or even:
        >>> notes = [['C', 5, {'velocity': 20}], ['E', 6, {'velocity': 20}]]
        """
        if hasattr(notes, "notes"):
            for x in notes.notes:
                self.add_note(x)
            return self.notes
        elif hasattr(notes, "name"):
            self.add_note(notes)
            return self.notes
        elif isinstance(notes, six.string_types):
            self.add_note(notes)
            return self.notes
        for x in notes:
            if isinstance(x, list) and len(x) != 1:
                if len(x) == 2:
                    self.add_note(x[0], x[1])
                else:
                    self.add_note(x[0], x[1], x[2])
            else:
                self.add_note(x)
        return self.notes

    def from_chord(self, shorthand):
        """Shortcut to from_chord_shorthand."""
        return self.from_chord_shorthand(shorthand)

    def from_chord_shorthand(self, shorthand):
        """Empty the container and add the notes in the shorthand.

        See mingus.core.chords.from_shorthand for an up to date list of
        recognized format.

        Example:
        >>> NoteContainer().from_chord_shorthand('Am')
        ['A-4', 'C-5', 'E-5']
        """
        self.empty()
        self.add_notes(chords.from_shorthand(shorthand))
        return self

    def from_interval(self, startnote, shorthand, up=True):
        """Shortcut to from_interval_shorthand."""
        return self.from_interval_shorthand(startnote, shorthand, up)

    def from_interval_shorthand(self, startnote, shorthand, up=True):
        """Empty the container and add the note described in the startnote and
        shorthand.

        See core.intervals for the recognized format.

        Examples:
        >>> nc = NoteContainer()
        >>> nc.from_interval_shorthand('C', '5')
        ['C-4', 'G-4']
        >>> nc.from_interval_shorthand('C', '5', False)
        ['F-3', 'C-4']
        """
        self.empty()
        if isinstance(startnote, six.string_types):
            startnote = Note(startnote)
        n = Note(startnote.name, startnote.octave, startnote.dynamics)
        n.transpose(shorthand, up)
        self.add_notes([startnote, n])
        return self

    def from_progression(self, shorthand, key="C"):
        """Shortcut to from_progression_shorthand."""
        return self.from_progression_shorthand(shorthand, key)

    def from_progression_shorthand(self, shorthand, key="C"):
        """Empty the container and add the notes described in the progressions
        shorthand (eg. 'IIm6', 'V7', etc).

        See mingus.core.progressions for all the recognized format.

        Example:
        >>> NoteContainer().from_progression_shorthand('VI')
        ['A-4', 'C-5', 'E-5']
        """
        from mingus.core import progressions
        self.empty()
        chords = progressions.to_chords(shorthand, key)
        # warning Throw error, not a valid shorthand

        if chords == []:
            return False
        notes = chords[0]
        self.add_notes(notes)
        return self

    def _consonance_test(self, testfunc, param=None):
        """Private function used for testing consonance/dissonance."""
        n = list(self.notes)
        while len(n) > 1:
            first = n[0]
            for second in n[1:]:
                if param is None:
                    if not testfunc(first.name, second.name):
                        return False
                else:
                    if not testfunc(first.name, second.name, param):
                        return False
            n = n[1:]
        return True

    def is_consonant(self, include_fourths=True):
        """Test whether the notes are consonants.

        See the core.intervals module for a longer description on
        consonance.
        """
        return self._consonance_test(intervals.is_consonant, include_fourths)

    def is_perfect_consonant(self, include_fourths=True):
        """Test whether the notes are perfect consonants.

        See the core.intervals module for a longer description on
        consonance.
        """
        return self._consonance_test(intervals.is_perfect_consonant, include_fourths)

    def is_imperfect_consonant(self):
        """Test whether the notes are imperfect consonants.

        See the core.intervals module for a longer description on
        consonance.
        """
        return self._consonance_test(intervals.is_imperfect_consonant)

    def is_dissonant(self, include_fourths=False):
        """Test whether the notes are dissonants.

        See the core.intervals module for a longer description.
        """
        return not self.is_consonant(not include_fourths)

    def remove_note(self, note, octave=-1):
        """Remove note from container.

        The note can either be a Note object or a string representing the
        note's name. If no specific octave is given, the note gets removed
        in every octave.
        """
        res = []
        for x in self.notes:
            if isinstance(note, six.string_types):
                if x.name != note:
                    res.append(x)
                else:
                    if x.octave != octave and octave != -1:
                        res.append(x)
            else:
                if x != note:
                    res.append(x)
        self.notes = res
        return res

    def remove_notes(self, notes):
        """Remove notes from the containers.

        This function accepts a list of Note objects or notes as strings and
        also single strings or Note objects.
        """
        if isinstance(notes, six.string_types):
            return self.remove_note(notes)
        elif hasattr(notes, "name"):
            return self.remove_note(notes)
        else:
            for x in notes:
                self.remove_note(x)
            return self.notes

    def remove_duplicate_notes(self):
        """Remove duplicate and enharmonic notes from the container."""
        res = []
        for x in self.notes:
            if x not in res:
                res.append(x)
        self.notes = res
        return res

    def sort(self):
        """Sort the notes in the container from low to high."""
        self.notes.sort()

    def augment(self):
        """Augment all the notes in the NoteContainer."""
        for n in self.notes:
            n.augment()

    def diminish(self):
        """Diminish all the notes in the NoteContainer."""
        for n in self.notes:
            n.diminish()

    def determine(self, shorthand=False):
        """Determine the type of chord or interval currently in the
        container."""
        return chords.determine(self.get_note_names(), shorthand)

    def transpose(self, interval, up=True):
        """Transpose all the notes in the container up or down the given
        interval."""
        for n in self.notes:
            n.transpose(interval, up)
        return self

    def get_note_names(self):
        """Return a list with all the note names in the current container.

        Every name will only be mentioned once.
        """
        res = []
        for n in self.notes:
            if n.name not in res:
                res.append(n.name)
        return res

    def __repr__(self):
        """Return a nice and clean string representing the note container."""
        return str(self.notes)

    def __getitem__(self, item):
        """Enable the use of the container as a simple array.

        Example:
        >>> n = NoteContainer(['C', 'E', 'G'])
        >>> n[0]
        'C-4'
        """
        return self.notes[item]

    def __setitem__(self, item, value):
        """Enable the use of the [] notation on NoteContainers.

        This function accepts Notes and notes as string.

        Example:
        >>> n = NoteContainer(['C', 'E', 'G'])
        >>> n[0] = 'B'
        >>> n
        ['B-4', 'E-4', 'G-4']
        """
        if isinstance(value, six.string_types):
            n = Note(value)
            self.notes[item] = n
        else:
            self.notes[item] = value
        return self.notes

    def __add__(self, notes):
        """Enable the use of the '+' operator on NoteContainers.

        Example:
        >>> n = NoteContainer(['C', 'E', 'G'])
        >>> n + 'B'
        ['C-4', 'E-4', 'G-4', 'B-4']
        """
        self.add_notes(notes)
        return self

    def __sub__(self, notes):
        """Enable the use of the '-' operator on NoteContainers.

        Example:
        >>> n = NoteContainer(['C', 'E', 'G'])
        >>> n - 'E'
        ['C-4', 'G-4']
        """
        self.remove_notes(notes)
        return self

    def __len__(self):
        """Return the number of notes in the container."""
        return len(self.notes)

    def __eq__(self, other):
        """Enable the '==' operator for NoteContainer instances."""
        for x in self:
            if x not in other:
                return False
        return True

class Track(object):

    """A track object.

    The Track class can be used to store Bars and to work on them.

    The class is also designed to be used with Instruments, but this is
    optional.

    Tracks can be stored together in Compositions.
    """

    bars = []
    instrument = None
    name = "Untitled"  # Will be looked for when saving a MIDI file.
    tuning = None  # Used by tablature

    def __init__(self, instrument=None):
        self.bars = []
        self.instrument = instrument

    def add_bar(self, bar):
        """Add a Bar to the current track."""
        self.bars.append(bar)
        return self

    def add_notes(self, note, duration=None):
        """Add a Note, note as string or NoteContainer to the last Bar.

        If the Bar is full, a new one will automatically be created.

        If the Bar is not full but the note can't fit in, this method will
        return False. True otherwise.

        An InstrumentRangeError exception will be raised if an Instrument is
        attached to the Track, but the note turns out not to be within the
        range of the Instrument.
        """
        if self.instrument != None:
            if not self.instrument.can_play_notes(note):
                raise InstrumentRangeError(
                    "Note '%s' is not in range of the instrument (%s)"
                    % (note, self.instrument)
                )
        if duration == None:
            duration = 4

        # Check whether the last bar is full, if so create a new bar and add the
        # note there
        if len(self.bars) == 0:
            self.bars.append(Bar())
        last_bar = self.bars[-1]
        if last_bar.is_full():
            self.bars.append(Bar(last_bar.key, last_bar.meter))
            # warning should hold note if it doesn't fit

        return self.bars[-1].place_notes(note, duration)

    def get_notes(self):
        """Return an iterator that iterates through every bar in the this
        track."""
        for bar in self.bars:
            for beat, duration, notes in bar:
                yield beat, duration, notes

    def from_chords(self, chords, duration=1):
        """Add chords to the Track.

        The given chords should be a list of shorthand strings or list of
        list of shorthand strings, etc.

        Each sublist divides the value by 2.

        If a tuning is set, chords will be expanded so they have a proper
        fingering.

        Example:
        >>> t = Track().from_chords(['C', ['Am', 'Dm'], 'G7', 'C#'], 1)
        """
        tun = self.get_tuning()

        def add_chord(chord, duration):
            if isinstance(chord, list):
                for c in chord:
                    add_chord(c, duration * 2)
            else:
                chord = NoteContainer().from_chord(chord)
                if tun:
                    chord = tun.find_chord_fingering(
                        chord, return_best_as_NoteContainer=True
                    )
                if not self.add_notes(chord, duration):
                    # This should be the standard behaviour of add_notes
                    dur = self.bars[-1].value_left()
                    self.add_notes(chord, dur)

                    # warning should hold note
                    self.add_notes(chord, value.subtract(duration, dur))

        for c in chords:
            if c is not None:
                add_chord(c, duration)
            else:
                self.add_notes(None, duration)
        return self

    def get_tuning(self):
        """Return a StringTuning object.

        If an instrument is set and has a tuning it will be returned.
        Otherwise the track's one will be used.
        """
        if self.instrument and self.instrument.tuning:
            return self.instrument.tuning
        return self.tuning

    def set_tuning(self, tuning):
        """Set the tuning attribute on both the Track and its instrument (when
        available).

        Tuning should be a StringTuning or derivative object.
        """
        if self.instrument:
            self.instrument.tuning = tuning
        self.tuning = tuning
        return self

    def transpose(self, interval, up=True):
        """Transpose all the notes in the track up or down the interval.

        Call transpose() on every Bar.
        """
        for bar in self.bars:
            bar.transpose(interval, up)
        return self

    def augment(self):
        """Augment all the bars in the Track."""
        for bar in self.bars:
            bar.augment()
        return self

    def diminish(self):
        """Diminish all the bars in the Track."""
        for bar in self.bars:
            bar.diminish()
        return self

    def __add__(self, value):
        """Enable the '+' operator for Tracks.

        Notes, notes as string, NoteContainers and Bars accepted.
        """
        if hasattr(value, "bar"):
            return self.add_bar(value)
        elif hasattr(value, "notes"):
            return self.add_notes(value)
        elif hasattr(value, "name") or isinstance(value, six.string_types):
            return self.add_notes(value)

    def test_integrity(self):
        """Test whether all but the last Bars contained in this track are
        full."""
        for b in self.bars[:-1]:
            if not b.is_full():
                return False
        return True

    def __eq__(self, other):
        """Enable the '==' operator for tracks."""
        for x in range(0, len(self.bars) - 1):
            if self.bars[x] != other.bars[x]:
                return False
        return True

    def __getitem__(self, index):
        """Enable the '[]' notation for Tracks."""
        return self.bars[index]

    def __setitem__(self, index, value):
        """Enable the '[] =' notation for Tracks.

        Throw an UnexpectedObjectError if the value being set is not a
        mingus.containers.Bar object.
        """
        if not hasattr(value, "bar"):
            raise UnexpectedObjectError(
                "Unexpected object '%s', "
                "expecting a mingus.containers.Barobject" % value
            )
        self.bars[index] = value

    def __repr__(self):
        """Return a string representing the class."""
        return str([self.instrument, self.bars])

    def __len__(self):
        """Enable the len() function for Tracks."""
        return len(self.bars)
